cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 10 76% 19%;
    --card: 0 0% 100%;
    --card-foreground: 10 76% 19%;
    --popover: 0 0% 100%;
    --popover-foreground: 10 76% 19%;
    --primary: 10 63% 29%;
    --primary-foreground: 10 100% 97%;
    --secondary: 10 94% 94%;
    --secondary-foreground: 10 63% 29%;
    --muted: 10 94% 94%;
    --muted-foreground: 10 85% 58%;
    --accent: 10 94% 94%;
    --accent-foreground: 10 63% 29%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 10 100% 97%;
    --border: 10 93% 89%;
    --input: 10 93% 89%;
    --ring: 10 76% 19%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 10 76% 19%;
    --foreground: 10 100% 97%;
    --card: 10 76% 19%;
    --card-foreground: 10 100% 97%;
    --popover: 10 76% 19%;
    --popover-foreground: 10 100% 97%;
    --primary: 10 100% 97%;
    --primary-foreground: 10 63% 29%;
    --secondary: 10 70% 33%;
    --secondary-foreground: 10 100% 97%;
    --muted: 10 70% 33%;
    --muted-foreground: 10 92% 68%;
    --accent: 10 70% 33%;
    --accent-foreground: 10 100% 97%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 10 100% 97%;
    --border: 10 70% 33%;
    --input: 10 70% 33%;
    --ring: 10 94% 80%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
